"""Write constants_gen.go: the literal constants of the Python installer modules.

Run from the repository root:
    python server/internal/installer/testdata/gen_constants.py > server/internal/installer/constants_gen.go
"""
import json
import sys

sys.path.insert(0, '.')
from backend.agents import core_install_script as core  # noqa: E402
from backend.agents import gateway_install_script as gateway  # noqa: E402
from backend.agents import go_install_script as go  # noqa: E402
from backend.agents import install_command_store as store  # noqa: E402


def q(value):
    return json.dumps(value, ensure_ascii=False)


CONSTANTS = [
    ('coreForwardingBlock', core._CORE_FORWARDING_BLOCK),
    ('installerForwardingBlock', core._INSTALLER_FORWARDING_BLOCK),
    ('AgentCoreInstallInterface', go.AGENT_CORE_INSTALL_INTERFACE),
    ('DNSHAPreparationInterface', go.DNS_HA_PREPARATION_INTERFACE),
    ('agentInitDetection', go._AGENT_INIT_DETECTION),
    ('coreInitDetection', go._CORE_INIT_DETECTION),
    ('aioForwardingHead', go._AIO_FORWARDING_HEAD),
    ('aioForwardingRoot', go._AIO_FORWARDING_ROOT),
    ('AIOForwardingHookComment', go.AIO_FORWARDING_HOOK_COMMENT),
    ('StandaloneForwardingHookComment', go.STANDALONE_FORWARDING_HOOK_COMMENT),
    ('StandaloneForwardingHook', go.STANDALONE_FORWARDING_HOOK),
    ('StandaloneForwardingUnsupported', go.STANDALONE_FORWARDING_UNSUPPORTED),
    ('InstallerForwardingEnvironment', go.INSTALLER_FORWARDING_ENVIRONMENT),
    ('InstallerForwardingEnvironmentEnd', go.INSTALLER_FORWARDING_ENVIRONMENT_END),
    ('standaloneGatewayRecordRefusal', go._STANDALONE_GATEWAY_RECORD_REFUSAL),
    ('standaloneForwardingPrepare', go._STANDALONE_FORWARDING_PREPARE),
    ('standaloneForwardingCleanup', go._STANDALONE_FORWARDING_CLEANUP),
    ('StaleScript', store.STALE_SCRIPT),
]

out = ['// Code generated by testdata/gen_constants.py from backend/agents; DO NOT EDIT.', '',
       'package installer', '', 'const (']
for name, value in CONSTANTS:
    out.append(f'\t{name} = {q(value)}')
out.append(')')
out.append('')
for name, table in (('SelectiveText', gateway.SELECTIVE_TEXT), ('FullTunText', gateway.FULL_TUN_TEXT)):
    out.append(f'// {name} is {"SELECTIVE_TEXT" if name == "SelectiveText" else "FULL_TUN_TEXT"}.')
    out.append(f'var {name} = []textItem{{')
    for key, value in table.items():
        out.append(f'\t{{{q(key)}, {q(value)}}},')
    out.append('}')
    out.append('')
out.append('// CoreReleases is CORE_RELEASES (services in order).')
out.append('var CoreReleases = []CoreRelease{')
for service, release in gateway.CORE_RELEASES.items():
    assert list(release) == ['version', 'linux-amd64', 'linux-arm64']
    out.append(f'\t{{Service: {q(service)}, Version: {q(release["version"])}, Assets: map[string]ReleaseAsset{{')
    for arch in ('linux-amd64', 'linux-arm64'):
        out.append(f'\t\t{q(arch)}: {{URL: {q(release[arch]["url"])}, SHA256: {q(release[arch]["sha256"])}}},')
    out.append('\t}},')
out.append('}')
print('\n'.join(out))
